\label{MT}
			Let $W$ be a finite Coxeter group with $S=\{s_1,\ldots,s_n\}$ as its Coxeter generating set.
			\begin{enumerate}
				\item[{\rm(a)}]
				There is an order of all conjugacy classes of $W$: $C_1,\ldots,C_r$ and a sequence $\alpha_1,\ldots,\alpha_r\in\mathbb{N}^n$ such that
				\begin{align*}
					&\{g=\phi(w):{\rm sig}(w)=\alpha_i\}\cap C_i\neq\varnothing\quad\text{for}\ i\in[r],
					\\
					&\{g=\phi(w):{\rm sig}(w)=\alpha_i\}\cap C_j=\varnothing\quad\text{for}\ i,j\in[r]\ \text{and}\ j>i.
			    \end{align*}
			    \item[{\rm(b)}]
			    For two finite dimensional complex linear representations $\rho_1$ and $\rho_2$ for $W$, $d(S,\rho_1)=d(S,\rho_2)$ if and only if $\rho_1\cong\rho_2$.
            \end{enumerate}

Let $M=(m_{ij})_{1\leq i,j\leq n}$ be a symmetric $n\times n$ matrix with entries from $\mathbb{N}\cup \{\infty\}$ such that $m_{ii}=1$ for all $i\in[n]$ and $m_{ij}>1$ whenever $i\neq j$. The {\it Coxeter group} of type $M$ is the group
				\begin{equation*}
					W(M)=\langle\{s_1,\ldots,s_n\}\ |\ \{(s_is_j)^{m_{ij}}=1,\ i,j\in [n],m_{ij}<\infty\}\rangle.
				\end{equation*}
				$S=\{s_1,\ldots,s_n\}$ is called the {\it Coxeter generating set}. If no confusion is imminent, we write $W$ instead of $W(M)$. The pair $(W,S)$ is called the {\it Coxeter system} of type $M$.

\label{refrep}
    		Let $(W,S)$ be a Coxeter system.
    		\begin{enumerate}
    			\item[{\rm(a)}]
    			The mapping $w\mapsto\sigma_w$ given by $\sigma_w=\sigma_{r_1}\cdots\sigma_{r_q}$ whenever $w=s_{r_1}\cdots s_{r_q} \\ \in W$ with $r_j\in [n]$ ($j\in[q]$) defines a linear representation of $W$ on $V$, which is called the reflection representation (or the geometric representation) of $W$, denoted by $\rho_{\it ref}$.
    			\item[{\rm(b)}]
    			The reflection representation of $W$ is faithful.
    		\end{enumerate}

\label{Tsig}
			Let $G$ be any finitely generated group with generating set $S=\{s_1,\ldots,s_n\}$, and $\rho_1,\rho_2 \in {\mathcal R}(G)$. If $d(S,\rho_1)=d(S,\rho_2)$, then for each given $\alpha\in\mathbb{N}^n$, we have
			\begin{equation}\label{sig}
				\sum_{{\rm sig}(w)=\alpha} \chi_{\rho_1}(w)=\sum_{{\rm sig}(w)=\alpha} \chi_{\rho_2}(w)
			\end{equation}
			where $\chi_{\rho_i}$ denotes the character of $\rho_i$.

\label{evdef}
			Let $G$ be any finitely generated group with finite number of conjugacy classes $C_1,\ldots,C_r$, and $S=\{s_1,\ldots,s_n\}$ be the generating set. Given a signature $\alpha =(a_1,\ldots,a_n)$, $E_{\alpha}\coloneqq\{u\in M(S):{\rm sig}(u)=\alpha\}$. The {\it signature vector} of $\alpha$ is
				\begin{equation*}
					V_{\alpha}=(|E_{\alpha}\cap \phi^{-1}(C_1)|,\ldots,|E_{\alpha}\cap \phi^{-1}(C_r)|).
				\end{equation*}

Let $G,S$ and $C_i$ be as in Definition \refeq{evdef}. A sequence $\alpha_1,\ldots,\\\alpha_r$ of signatures is called an {\it independent signature sequence} (abbreviated as {\rm ISS}) if $V_{\alpha_1},\ldots,V_{\alpha_r}$ is linearly independent. Suppose $\alpha_1,\ldots,\alpha_r$ is an {\rm ISS}, the corresponding {\it independent signature matrix} (abbreviated as {\rm ISM}) is the matrix
				\begin{equation*}
					\left(
					\begin{array}{c}
						V_{\alpha_1}\\
						\vdots\\
						V_{\alpha_r}\\
					\end{array}      	
					\right).        	
				\end{equation*}

Let $\alpha_1,\ldots,\alpha_r$ be an {\rm ISS} of $G$. By Theorem \refeq{Tsig}, $V_{\alpha}\mathcal{C}_1=V_{\alpha}\mathcal{C}_2$ for any signature $\alpha$. Therefore
			\begin{equation*}
				\left(
				\begin{array}{c}
					V_{\alpha_1}\\
					\vdots\\
					V_{\alpha_r}\\
				\end{array}      	
				\right)        	
				\mathcal{C}_1=
				\left(
				\begin{array}{c}
					V_{\alpha_1}\\
					\vdots\\
					V_{\alpha_r}\\
				\end{array}      	
				\right)    
				\mathcal{C}_2.			
			\end{equation*}
			Since the {\rm ISM} is invertible, we have $\mathcal{C}_1=\mathcal{C}_2$, i.e. $\chi_{\rho_1}(C_i)=\chi_{\rho_2}(C_i)$ for each $i\in[r]$. Thus $\chi_{\rho_1}(g)=\chi_{\rho_2}(g)$ for each $g\in G$.

\label{countlm}
				Let $G=G_1\times G_2$, where $G_1$ and $G_2$ are finitely generated groups. Generating sets of $G_1,G_2$ and $G$ are $S,T$ and $S\sqcup T$, respectively. Given $w=r_1\cdots r_n \in M(S\sqcup T)$ and $r_i\in S\sqcup T$, let
				\begin{equation*}
					r_i^{(1)}=
					\begin{cases}
						r_i & r_i\in S\\
						\varepsilon & r_i\in T
					\end{cases}
					,
					\quad
					r_i^{(2)}=
					\begin{cases}
						\varepsilon & r_i\in S\\
						r_i & r_i\in T
					\end{cases}
					.
				\end{equation*}
				Let $w^{(1)}=r_1^{(1)}r_2^{(1)}\cdots r_n^{(1)}$, $w^{(2)}=r_1^{(2)}r_2^{(2)}\cdots r_n^{(2)}$, and $f$ denote the map $w\mapsto w^{(1)}w^{(2)}$, then $|f^{-1}(w_1w_2)|=|w_1w_2|!/(|w_1|!|w_2|!)$ for any $w_1\in M(S)$, $w_2\in M(T)$.

\label{g1g2prop}
			Let $G=G_1\times G_2$, where $G_1$ and $G_2$ are any finitely generated groups with finite number of conjugacy classes. Generating sets of $G_1,G_2$ and $G$ are $S,T$ and $S\sqcup T$ respectively.
			
			\begin{enumerate}
				\item[{\rm(a)}]
				If both $G_1$ and $G_2$ have an {\rm ISS}, then $G$ has an {\rm ISS}.
				\item[{\rm(b)}]
				If both $G_1$ and $G_2$ have a lower triangular {\rm ISM}, then $G$ has a lower triangular {\rm ISM}.
			\end{enumerate}

Let $C_{i,1},\ldots,C_{i,r_i}$ be all conjugacy classes of $G_i$ for $i=1,2$. Suppose $\alpha_1,\ldots,\alpha_{r_1}$ is an {\rm ISS} of $G_1$; $\beta_1,\ldots,\beta_{r_2}$ is an {\rm ISS} of $G_2$. Let $\alpha_i||\beta_j$ denote the signature spliced by $\alpha_i$ and $\beta_j$, for example, $(1,2)||(3,4)\coloneqq(1,2,3,4)$. Consider signature sequence 
			\begin{equation}\label{g1g2sig}
				\alpha_1||\beta_1,\ldots,\alpha_1||\beta_{r_2},\ldots,\alpha_{r_1}||\beta_1,\ldots,\alpha_{r_1}||\beta_{r_2}.
			\end{equation} 
			We will prove that it is an {\rm ISS} of $G$. For each $\alpha_i$ and $\beta_j$, we have
			\begin{equation*}
				E_{\alpha_i||\beta_j}=\bigsqcup_{\substack{u_1\in E_{\alpha_i}\\ u_2\in E_{\beta_j}}}f^{-1}(u_1u_2)
			\end{equation*}
			where $f$ is as defined in Lemma \refeq{countlm}. Let $V_{\alpha_i}=(x_{i,1},\ldots,x_{i,r_1})$ and $V_{\beta_j}=(y_{j,1},\ldots,y_{j,r_2})$. For each conjugacy class $C_{1,k}\times C_{2,l}$, it follows that
			\begin{equation*}
				\begin{aligned}
					&|E_{\alpha_i||\beta_j}\cap \phi^{-1}(C_{1,k}\times C_{2,l})|\\
					=&|\bigsqcup_{\substack{u_1\in E_{\alpha_i}\\ u_2\in E_{\beta_j}}}(f^{-1}(u_1u_2)\cap \phi^{-1}(C_{1,k}\times C_{2,l}))|
					\\
					=&\sum_{\substack{u_1\in E_{\alpha_i}\\ u_2\in E_{\beta_j}}}|f^{-1}(u_1u_2)\cap \phi^{-1}(C_{1,k}\times C_{2,l})|\\
					=&\sum_{\substack{u_1\in E_{\alpha_i}\cap \phi^{-1}(C_{1,k})\\ u_2\in E_{\beta_j}\cap \phi^{-1}(C_{2,l})}}|f^{-1}(u_1u_2)|
					\\
					=&\sum_{\substack{u_1\in E_{\alpha_i}\cap \phi^{-1}(C_{1,k})\\ u_2\in E_{\beta_j}\cap \phi^{-1}(C_{2,l})}}\frac{(|\alpha_i|+|\beta_j|)!}{|\alpha_i|!|\beta_j|!}\\
					=&|E_{\alpha_i}\cap \phi^{-1}(C_{1,k})|\cdot|E_{\beta_j}\cap \phi^{-1}(C_{2,l})|\frac{(|\alpha_i|+|\beta_j|)!}{|\alpha_i|!|\beta_j|!}
					\\
					=&\frac{(|\alpha_i|+|\beta_j|)!}{|\alpha_i|!|\beta_j|!}x_{i,k}y_{j,l}.
				\end{aligned}
			\end{equation*}
			Arrange all the conjugacy classes in $G$ as
			\begin{equation*}
				C_{1,1}\times C_{2,1},\ldots,C_{1,1}\times C_{2,r_2},\ldots,C_{1,r_1}\times C_{2,1},\ldots,C_{1,r_1}\times C_{2,r_2}.
			\end{equation*}
			Then we have
			\begin{equation*}
				V_{\alpha_i||\beta_j}= \frac{(|\alpha_i|+|\beta_j|)!}{|\alpha_i|!|\beta_j|!}(x_{i,1}y_{j,1},\ldots,x_{i,1}y_{j,r_2},\ldots,x_{i,r_1}y_{j,1},\ldots,x_{i,r_1}y_{j,r_2}).
			\end{equation*}
			Let $M_{i,j}\coloneqq(|\alpha_i|+|\beta_j|)!/(|\alpha_i|!|\beta_j|!)$, we have
			\begin{equation}\label{csmeq}
			\begin{gathered}
				\begin{pmatrix}
					V_{\alpha_1||\beta_1}\\
					\vdots\\
					V_{\alpha_1||\beta_{r_2}}\\
					\vdots\\
					V_{\alpha_{r_1}||\beta_1}\\
					\vdots\\
					V_{\alpha_{r_1}||\beta_{r_2}}\\
				\end{pmatrix}      	
				=
				\begin{pmatrix}
					M_{1,1}&~&~&~&~&~&~\\
					~&\ddots&~&~&~&~&~\\
					~&~&M_{1,r_2}&~&~&~&~\\
					~&~&~&\ddots&~&~&~\\
					~&~&~&~&M_{r_1,1}&~&~\\
					~&~&~&~&~&\ddots&~\\
					~&~&~&~&~&~&M_{r_1,r_2}\\
				\end{pmatrix}
				\boldsymbol{\cdot}\\
				\begin{pmatrix}	
					V_{\alpha_1}\\
					\vdots\\
					V_{\alpha_{r_1}}\\   	
				\end{pmatrix}			
				\bigotimes
				\begin{pmatrix}	
					V_{\beta_1}\\
					\vdots\\
					V_{\beta_{r_2}}\\    	
				\end{pmatrix}.	
			\end{gathered}
		    \end{equation}
			Then
			\begin{equation*}
				{\rm det}
				\begin{pmatrix}
					V_{\alpha_1||\beta_1}\\
					\vdots\\
					V_{\alpha_{r_1}||\beta_{r_2}}\\
				\end{pmatrix} 
				=
				(\prod_{i=1}^{r_1}\prod_{j=1}^{r_2}M_{i,j})
				{\rm det}^{r_2}
				\begin{pmatrix}	
					V_{\alpha_1}\\
					\vdots\\
					V_{\alpha_{r_1}}\\   	
				\end{pmatrix}
				{\rm det}^{r_1}
				\begin{pmatrix}	
					V_{\beta_1}\\
					\vdots\\
					V_{\beta_{r_2}}\\    	
				\end{pmatrix}			
				\neq 0.
			\end{equation*}
			Hence sequence \eqref{g1g2sig} is an {\rm ISS} of $G$.
			
			If the corresponding {\rm ISMs} of $\alpha_1,\ldots,\alpha_{r_1}$ and $\beta_1,\ldots,\beta_{r_2}$ are both lower triangular matrices, then the corresponding {\rm ISM} of \eqref{g1g2sig} is also a lower triangular matrix by equation \eqref{csmeq}.

\label{dpc}
			Let $G=G_1\times\cdots\times G_m$, where $G_1,\ldots,G_m$ are any finitely generated groups with finite number of conjugacy classes. Generating sets of $G_1,\ldots,G_m$ and $G$ are $S_1,\ldots,S_m$ and $S=\bigsqcup_{i=1}^mS_i$ respectively.
			\begin{enumerate}
				\item[{\rm(a)}]
				If each $G_i$ has an {\rm ISS}, then $G$ has an {\rm ISS}.
				\item[{\rm(b)}]
				If each $G_i$ has a lower triangular {\rm ISM}, then $G$ has a lower triangular {\rm ISM}.
			\end{enumerate}

\label{csslm}
			Let $\alpha_i=(a_{i,1},\ldots,a_{i,n})\in \mathbb{C}^n$, where $i\in[m]$ and $m\geq n$. Let $\gamma(\alpha_i)\coloneqq\{j:a_{i,j}\neq0\}$. If the following holds:
			\begin{enumerate}
				\item [\rm (a)]
				$|\gamma(\alpha_1)|=1$,
				\item [\rm (b)]
				$|\bigcup_{i=1}^{m}\gamma(\alpha_i)|=n$,
				\item [\rm (c)]
				$|\gamma(\alpha_k)\setminus\bigcup_{i=1}^{k-1}\gamma(\alpha_i)|=0\ {\rm or}\ 1$ for each $k\in\{2,\ldots,m\}$.
			\end{enumerate}
			Then there is a subsequence $\alpha_{p_1},\ldots,\alpha_{p_n}$ that satisfies:
			\begin{enumerate}
				\item [\rm (1)]
				$\alpha_{p_1},\ldots,\alpha_{p_n}$ is linearly independent,
				\item [\rm (2)]
				the matrix 
				\begin{equation*}
					\left(\begin{array}{c}
						\alpha_{p_1}\\
						\vdots\\
						\alpha_{p_n}\\
					\end{array}\right)
				\end{equation*}
				can be transformed into a lower triangular matrix by permuting the columns.
			\end{enumerate}

Let
			\begin{equation*}
				A=\{\alpha_k:k\geq2, |\gamma(\alpha_k)\setminus\bigcup_{i=1}^{k-1}\gamma(\alpha_i)|=1\}\cup\{\alpha_1\}.
			\end{equation*} 
			By (a), (b) and (c), we have $|A|=n$. Let $A=\{\alpha_{p_1},\ldots,\alpha_{p_n}\}$ where $p_1<\cdots<p_n$. For each $r\in[n]$, let $\gamma(\alpha_{p_r})\setminus\bigcup_{i=1}^{p_r-1}\gamma(\alpha_i)=\{q_r\}$, we have $a_{p_r,q_r}\neq 0$ and $a_{p_i,q_r}=0$ for each $i< r$. Thus, by permuting the columns of the matrix $(a_{p_i,j})_{i,j\in[n]}$ according to $q_1,\ldots, q_n$, we obtain an invertible lower triangular matrix $(a_{p_i,q_j})_{i,j\in[n]}$. Therefore, for the sequence $\alpha_{p_1},\ldots,\alpha_{p_n}$, properties (1) and (2) hold.

We define a partial order on $\mathbb{N}^2$. Let $\alpha,\beta\in \mathbb{N}^2$, $\alpha=(a_1,a_2$), $\beta=(b_1,b_2)$. Let $\alpha\leq\beta$ if $(|\alpha|,a_1,a_2)\leq_{\rm lex}(|\beta|,b_1,b_2)$ where $\leq_{\rm lex}$ is the lexicographic order on $\mathbb{N}^3$. It can be seen that $\leq$ is a total order.
			\par
			Let $C_1,\ldots,C_r$ be all conjugacy classes of $W$. For each $i\in[r]$, take a word $w_i\in \phi^{-1}(C_i)$, let $\alpha_i={\rm sig}(w_i)$, let $H=\{w_1,\ldots,w_r\}$. Let
			\begin{equation*}
				A=\{\alpha\in \mathbb{N}^2:\exists i\ s.t.\ \alpha\leq\alpha_i\},
			\end{equation*}
			Clearly $|A|<\infty$, so let $A=\{\beta_1,\ldots, \beta_N\}$, where $\beta_1<\cdots<\beta_N$. Then we consider $\{V_{\beta_1},\ldots,V_{\beta_N}\}$ where $V_{\beta_i}$ defined in Definition \refeq{evdef}. Let $\gamma$ be as defined in Lemma \refeq{csslm}. Since $\beta_1=(0,0)$, we have $|\gamma(V_{\beta_1})|=1$. For each conjugacy class $C_h$, note that $w_h\in \phi^{-1}(C_h)$ and $\alpha_h={\rm sig}(w_h)\in A$, so $h\in\gamma(V_{\alpha_h})\in \bigcup_{i=1}^N\gamma(V_{\beta_i})$. For the arbitrariness of $h$, we have $|\bigcup_{i=1}^N\gamma(V_{\beta_i})|=r$. \par
			For each $k\in \{2,\ldots,N\}$, let $\beta_k=(b_1,b_2)$. If $|b_1-b_2|\geq 2$, then for each $h\in\gamma(V_{\beta_k})$, there exists a $w=t_1\cdots t_{|\beta_k|}\in \phi^{-1}(C_h)$, $t_i\in\{g_1,g_2\}$ such that ${\rm sig}(w)=\beta_k$ and $t_j=t_{j+1}$ for some $j$. Thus there is a $w'=t_1\cdots t_{j-1}t_{j+2}\cdots t_{|\beta_k|}$ such that $\phi(w')=\phi(w)$ and ${\rm sig}(w')<{\rm sig}(w)=\beta_k$. So ${\rm sig}(w')\in A$ and $h\in\gamma(V_{{\rm sig}(w')})\subseteq\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})$. For the arbitrariness of $h$, we have $|\gamma(V_{\beta_k})\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})|=0$.\par
			If $|b_1-b_2|=1$, suppose $b_2=b_1+1$. If $b_1=0$, then $|\gamma(V_{\beta_k})|=1$ and $|\gamma(V_{\beta_k})\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})|=0\ {\rm or}\ 1$. If $b_1>0$, then $g_2g_1\cdots g_2g_1g_2\in E_{\beta_k}$ and is conjugate to $g_1$ or $g_2$. For each $w=t_1\cdots t_{|\beta_k|}\in E_{\beta_k}\setminus\{g_2g_1\cdots g_2g_1g_2\}$ where $t_i\in\{g_1,g_2\}$, there is a $t_j=t_{j+1}$ for some $j$. Thus for each $h\in\gamma(V_{\beta_k})$, there are $w,w'\in M(S)$ such that ${\rm sig}(w')<{\rm sig}(w)=\beta_k$ and $\phi(w')$ is conjugate to $\phi(w)$. Hence $h\in\gamma(V_{{\rm sig}(w')})\subseteq\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})$. For the arbitrariness of $h$, we have $|\gamma(V_{\beta_k})\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})|=0$.\par
			If $b_1=b_2$, then $g_1g_2\cdots g_1g_2,g_2g_1\cdots g_2g_1\in E_{\beta_k}$. Let
			\begin{equation*}
				\tilde{E}_{\beta_k}\coloneqq E_{\beta_k}\setminus\{g_1g_2\cdots g_1g_2, g_2g_1 \cdots g_2g_1\}.
			\end{equation*}
			For each $w=t_1t_2\cdots t_{|\beta_k|} \in \tilde{E}_{\beta_k}$, there is a $t_j=t_{j+1}$ for some $j$. Let
			\begin{equation*}
				V'=(|\tilde{E}_{\beta_k}\cap \phi^{-1}(C_1)|,\ldots,|\tilde{E}_{\beta_k}\cap \phi^{-1}(C_r)|).
			\end{equation*}
			By the same argument in the previous cases, we have $|\gamma(V')\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})|=0$. Since $g_1g_2\cdots g_1g_2$ and $g_2g_1 \cdots g_2g_1$ are in the same conjugacy class, the number of conjugacy classes in $E_{\beta_k}$ is at most one more than the number of conjugacy classes in $\tilde{E}_{\beta_k}$, so $|\gamma(V_{\beta_k})\setminus\gamma(V')|=0\ {\rm or}\ 1$. Thus $|\gamma(V_{\beta_k})\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\beta_i})|=0\ {\rm or}\ 1$.\par
			Consequently, by using Lemma \refeq{csslm}, there is a linearly independent subsequence $V_{\beta_{p_1}},\ldots,V_{\beta_{p_r}}$ of $V_{\beta_1},\ldots,V_{\beta_N}$, hence $\beta_{p_1},\ldots,\beta_{p_r}$ is an {\rm ISS} of $W$. Besides, with proper reordering of the conjugacy classes $C_1,\ldots,C_r$, the {\rm ISM} of $\beta_{p_1},\ldots,\beta_{p_r}$ can become a lower triangular matrix.

\label{ABDprop}
			Let $W$ be a finite Coxeter group of type ${\rm A_n}$, ${\rm B_n}$ or ${\rm D_{n+1}}$, and $S=\{g_1,g_2,\cdots\}$ is a set of Coxeter generators for $W$. Given a word $u\in M(S)$ and ${\rm sig}(u)=(a_1,\ldots,a_n)$ or $(a_1,\ldots,a_{n+1})$, let ${\rm ct}(u)\coloneqq(|u|,a_1,\ldots,a_{n-1})$.
			\begin{enumerate}
				\item[{\rm(a)}]
				For each word $w\in M(S)$, there exists a word $\tilde{w}$ such that $\phi(w)$ is conjugate to $\phi(\tilde{w})$ and ${\rm ct}(w)\geq_{\rm lex}{\rm ct}(\tilde{w})$ where $\leq_{\rm lex}$ is the lexicographic order on $\mathbb{N}^n$.
				\item[{\rm(b)}]
				Let words $w_1,w_2\in M(S)$, if ${\rm sig}(w_1)={\rm sig}(w_2)$ and ${\rm ct}(w_1)={\rm ct}(\tilde{w}_1)={\rm ct}(\tilde{w}_2)={\rm ct}(w_2)$, then $\phi(w_1)$ is conjugate to $\phi(w_2)$.
	    	\end{enumerate}

Let $C_1,\ldots,C_r$ be all conjugacy classes of $W$. Take a word $v_i\in \phi^{-1}(C_i)$ for each $i\in[r]$, let $H=\{v_1,\ldots,v_r\}$ and $J=\{w:\exists v_i\in H\ s.t.\ w\leq v_i\}$. Clearly we have $|J|<\infty$, so $(J,\leq)$ can extend to a totally ordered set $(J,\widetilde{\leq})$ (i.e. $w_i\leq w_j$ implies $w_i\widetilde{\leq}w_j$). So let $J=\{w_1,\ldots,w_N\}$, where $w_1\widetilde{<}\cdots\widetilde{<}w_N$. Let $\alpha_i={\rm sig}(w_i)$ for each $i\in[r]$.\par
			Since $w_1=\varepsilon$, it follows that $|\gamma(V_{\alpha_1})|=1$. For each $h\in[r]$, we have $v_h\in \phi^{-1}(C_h)$ and $v_h\in J$. Let $\alpha_k={\rm sig}(v_h)$, then $h\in\gamma(V_{\alpha_k})\subseteq\bigcup_{i=1}^N\gamma(V_{\alpha_i})$. For the arbitrariness of $h$, we have $|\bigcup_{i=1}^N\gamma(V_{\alpha_i})|=r$.
			\par
			For each $k\in\{2,\ldots,N\}$, by Proposition \refeq{ABDprop} part (a), we divide $E_{\alpha_k}$ into two parts:
			\begin{equation*}
				\hat{E}_{\alpha_k}\coloneqq E_{\alpha_k}\cap\{u:{\rm ct}(\tilde{u})<_{\rm lex}{\rm ct}(u)\}
			\end{equation*}
			and
			\begin{equation*}
				\bar{E}_{\alpha_k}\coloneqq E_{\alpha_k}\cap\{u:{\rm ct}(\tilde{u})={\rm ct}(u)\}.
			\end{equation*}
			Let
			\begin{equation*}
				V'=(|\hat{E}_{\alpha_k}\cap \phi^{-1}(C_1)|,\ldots,|\hat{E}_{\alpha_k}\cap \phi^{-1}(C_r)|).
			\end{equation*}	
			For each $h\in\gamma(V')$, there exists $u_0\in \hat{E}_{\alpha_k}$ and $u_0\in \phi^{-1}(C_h)$. Since ${\rm ct}(\tilde{u}_0)<_{\rm lex}{\rm ct}(u_0)={\rm ct}(w_k)$, we have $\tilde{u}_0<w_k$ and thus $\tilde{u}_0\in J$. Let $\tilde{u}_0=w_l$, ${\rm sig}(\tilde{u}_0)=\alpha_l$, then $w_l\widetilde{<}w_k$ and then $l<k$. Since $\phi(\tilde{u}_0)$ and $\phi(u_0)$ are in the same conjugacy class, $h\in \gamma(V_{\alpha_l})\subseteq\bigcup_{i=1}^{k-1}\gamma(V_{\alpha_i})$. For the arbitrariness of $h$, we have $\gamma(V')\subseteq\bigcup_{i=1}^{k-1}\gamma(V_{\alpha_i})$.
			\par
			Now consider words in $\bar{E}_{\alpha_k}$. Let $u_1,u_2\in \bar{E}_{\alpha_k}$, we have ${\rm sig}(u_1)={\rm sig}(u_2)$ and ${\rm ct}(u_1)={\rm ct}(\tilde{u}_1)={\rm ct}(\tilde{u}_2)={\rm ct}(u_2)$, so $\phi(u_1)$ and $\phi(u_2)$ are in the same conjugacy class by Proposition \refeq{ABDprop} part (b). Thus the number of conjugacy classes in $E_{\alpha_k}$ is at most one more number than the number of conjugacy classes in $\hat{E}_{\alpha_k}$. So we have $|\gamma(V_{\alpha_k})\setminus\gamma(V')|=0\ {\rm or}\ 1$, and $|\gamma(V_{\alpha_k})\setminus\bigcup_{i=1}^{k-1}\gamma(V_{\alpha_i})|=0\ {\rm or}\ 1$ since $\gamma(V')\subseteq\bigcup_{i=1}^{k-1}\gamma(V_{\alpha_i})$.\par 
			Therefore, by using Lemma \refeq{csslm}, there is a linearly independent subsequence $V_{\alpha_{p_1}},\ldots,V_{\alpha_{p_r}}$ of $V_{\alpha_1},\ldots,V_{\alpha_N}$, hence $\alpha_{p_1},\ldots,\alpha_{p_r}$ is an {\rm ISS} of $W$. Besides, with proper reordering of the conjugacy classes $C_1,\ldots,C_r$, the {\rm ISM} of $\alpha_{p_1},\ldots,\alpha_{p_r}$ can become a lower triangular matrix.

Let signature $\alpha\in\mathbb{N}^n$. The {\it non-cuspidal signature vector} of $\alpha$ is
				\begin{equation*}
					{\it NV}(\alpha)\coloneqq(|E_{\alpha}\cap \phi^{-1}({\it Ncus}_1)|,\ldots,|E_{\alpha}\cap \phi^{-1}({\it Ncus}_p)|).
				\end{equation*}
				The {\it cuspidal signature vector} of $\alpha$ is
				\begin{equation*}
					{\it CV}(\alpha)\coloneqq(|E_{\alpha}\cap \phi^{-1}({\it Cus}_1)|,\ldots,|E_{\alpha}\cap \phi^{-1}({\it Cus}_q)|).
				\end{equation*}

\begin{enumerate}
					\item[{\rm(a)}]
					A sequence $\alpha_1,\ldots,\alpha_p$ of signatures is called a {\it non-cuspidal signature sequence}  (abbreviated as {\rm NSS}) if
					\begin{enumerate}
						\item [1)]
						${\it NV}(\alpha_1),\ldots,{\it NV}(\alpha_p)$ is linearly independent.
						\item [2)]
						$|E_{\alpha_i}\cap \phi^{-1}({\it Cus}_j)|=0$ for each $i\in[p],\ j\in[q]$.
					\end{enumerate}
					Suppose $\alpha_1,\ldots,\alpha_p$ is an {\rm NSS}, the corresponding {\it non-cuspidal signature matrix} (abbreviated as {\rm NSM}) is the matrix
					\begin{equation*}
						\left(
						\begin{array}{c}
							{\it NV}(\alpha_1)\\
							\vdots\\
							{\it NV}(\alpha_p)\\
						\end{array}      	
						\right).        	
					\end{equation*}
					\item[{\rm(b)}]
					A sequence $\alpha_1,\ldots,\alpha_q$ of signatures is called a {\it cuspidal signature sequence} (abbreviated as {\rm CSS}) if ${\it CV}(\alpha_1),\ldots,{\it CV}(\alpha_q)$ is linearly independent. Suppose $\alpha_1,\ldots,\alpha_q$ is a {\rm CSS}, the corresponding {\it cuspidal signature matrix} (abbreviated as {\rm CSM}) is the matrix
					\begin{equation*}
						\left(
						\begin{array}{c}
							{\it CV}(\alpha_1)\\
							\vdots\\
							{\it CV}(\alpha_q)\\
						\end{array}      	
						\right).
					\end{equation*}
				\end{enumerate}

\label{cssp}
			\begin{enumerate}
				\item[{\rm(a)}]
				If $W$ has an {\rm NSS} and a {\rm CSS}, then $W$ has an {\rm ISS}.
				\item[{\rm(b)}]
				If $W$ has a lower triangular {\rm NSM} and a lower triangular {\rm CSM}, then $W$ has a lower triangular {\rm ISM}.
			\end{enumerate}

